// Isometric icon catalogue, vendored for the isometric view and the FossFLOW
// export. The deliverable is a self-contained offline HTML (like icons.ts and
// its Lucide catalogue): nothing can be fetched at run time, so the artwork is
// embedded as data URIs.
//
// Source: the "isoflow" collection of @isoflow/isopacks@0.0.10 (npm) -- the
// Isoflow project's own generic artwork (MIT), also redistributed by FossFLOW
// (Unlicense). Only the generic collection is taken: the AWS/Azure/GCP/K8s
// packs carry the vendors' own terms and stay out.
//
// The "3D" of an isometric board lives entirely in these drawings: the engine
// merely places them on a diamond grid (see iso-view.ts).

export interface IsoIcon {
  id: string;
  name: string;
  // SVG as a data URI, ready for an <image> href or a FossFLOW icon url.
  url: string;
}

export const ISO_ICONS: IsoIcon[] = [
  { id: "server", name: "server", url: "data:image/svg+xml;base64," },
  { id: "storage", name: "storage", url: "data:image/svg+xml;base64," },
  { id: "queue", name: "queue", url: "data:image/svg+xml;base64," },
  { id: "user", name: "user", url: "data:image/svg+xml;base64," },
  { id: "desktop", name: "desktop", url: "data:image/svg+xml;base64," },
  { id: "laptop", name: "laptop", url: "data:image/svg+xml;base64," },
  { id: "cloud", name: "cloud", url: "data:image/svg+xml;base64," },
  { id: "cronjob", name: "cronjob", url: "data:image/svg+xml;base64," },
  { id: "router", name: "router", url: "data:image/svg+xml;base64," },
  { id: "mail", name: "mail", url: "data:image/svg+xml;base64," },
];

// Which drawing an actor type gets. Same spirit as SHAPE_BY_TYPE in c4-dsl.ts:
// the commonest words only, and an unknown type stays a plain server rather
// than guessing -- except an external one, drawn as the cloud it is seen as.
const ICON_BY_TYPE: Record<string, string> = {
  queue: "queue",
  topic: "queue",
  broker: "queue",
  bus: "queue",
  database: "storage",
  storage: "storage",
  person: "user",
  human: "user",
  user: "user",
  batch: "cronjob",
  screen: "desktop",
  browser: "laptop",
  gateway: "router",
  esb: "router",
  proxy: "router",
  middleware: "router",
  mail: "mail",
  smtp: "mail",
  cloud: "cloud",
};

export function iconForType(type: string | undefined, external: boolean): string {
  const kept = ICON_BY_TYPE[(type ?? "").trim().toLowerCase()];
  if (kept) return kept;
  return external ? "cloud" : "server";
}
